  ('8884d6dc-4ffa-5fa1-87d4-1b32224ba48f', null, (select id from public.skills where slug = 'read-g9-character-setting-plot'), null, 'medium',
   $q$Which statement best describes how Ormond responds when he finds the pins in Pell's nest?$q$, $q$[{"text":"He angrily punishes her and forbids her to come near the tower again.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He praises her collection and tells her the clock never needed them.","is_correct":false,"misconception_token":"misreads-character"},{"text":"He takes the pins back himself without saying anything to her at all.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He calmly admits the pins are beautiful but helps her see what they cost.","is_correct":true}]$q$::jsonb, $q$He calmly admits the pins are beautiful but helps her see what they cost.$q$, $q$Ormond "did not shout" and says the pins are beautiful but "were also holding up the morning," which helps her understand the harm. Pell, not Ormond, carries the pins back, and later she sits beside him in the tower.$q$, 'draft', 'f602dc38-6f57-521f-9030-c7c6764339da')
