  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('119684ae-6375-56a3-bbaa-5ba66b7788db', null, (select id from public.skills where slug = 'read-g9-character-setting-plot'), null, 'hard',
   $q$How does Pell's final action of sitting beside Ormond each night develop the fable's lesson?$q$, $q$[{"text":"It shows she still wants the pins and is waiting for a second chance, so the lesson is that greed never ends.","is_correct":false,"misconception_token":"misreads-character"},{"text":"It shows she is being held prisoner as punishment, so the lesson is that thieves must always be caught.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows Ormond is too old to work alone, so the lesson is that the young must replace the old.","is_correct":false,"misconception_token":"off-theme"},{"text":"It shows she now values what the pins do, not just how they look, so she has learned the cost of small harms.","is_correct":true}]$q$::jsonb, $q$It shows she now values what the pins do, not just how they look, so she has learned the cost of small harms.$q$, $q$Pell chooses to learn "to hear when a gear began to slip," moving from loving the pins' shine to protecting what they do, which supports the moral that "a small theft can stop a great machine." Nothing suggests Ormond is too weak to work.$q$, 'draft', 'f602dc38-6f57-521f-9030-c7c6764339da')
