  ('d584d837-6f8d-540c-bb91-b7008a0d5a60', null, (select id from public.skills where slug = 'read-g9-character-setting-plot'), null, 'medium',
   $q$How does the setting of a late Thursday night with the press already running increase the pressure on Esther?$q$, $q$[{"text":"The press is about to break down, so she must act before the machine stops on its own.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Everyone else in town is asleep, so no one would ever learn the true winner's name.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Every passing minute prints more copies with the wrong name, so waiting makes the problem worse.","is_correct":true},{"text":"The darkness makes it hard for her to read the proof clearly, so she doubts her own memory.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Every passing minute prints more copies with the wrong name, so waiting makes the problem worse.$q$, $q$"Each sheet that slid off the roller carried the wrong name," so delay multiplies the error. Esther reads the headline twice and is sure of what she saw, so doubt is not the issue.$q$, 'draft', 'be92127d-d0c9-54f5-80f6-b8ebc41372f7')
